/// Offline civil days for the 24 crossings of apparent geocentric solar longitude,
/// computed with Skyfield and the NASA JPL DE440s ephemeris.
/// Generated by tools/generate_solar_terms.py, using IANA Asia/Taipei (historical offsets included).
enum SolarTerms {
    static let attribution = "節氣日期來源：NASA JPL DE440s 星曆，以 Skyfield 計算並換算為臺北日期"
    static let sourceURL = URL(string: "https://ssd.jpl.nasa.gov/planets/eph_export.html")!
    static let supportedYears = 1901...2100
    static let names = [
        "小寒", "大寒", "立春", "雨水", "驚蟄", "春分", "清明", "穀雨",
        "立夏", "小滿", "芒種", "夏至", "小暑", "大暑", "立秋", "處暑",
        "白露", "秋分", "寒露", "霜降", "立冬", "小雪", "大雪", "冬至"
    ]

    static func date(for name: String, year: Int, calendar: Calendar) -> Date? {
        guard calendar.identifier == .gregorian,
              supportedYears.contains(year),
              let index = names.firstIndex(of: name),
              let days = daysByYear?[year - supportedYears.lowerBound] else { return nil }
        let month = index / 2 + 1
        let day = days[index]
        guard let date = calendar.date(from: DateComponents(year: year, month: month, day: day)),
              calendar.dateComponents([.year, .month, .day], from: date) ==
                DateComponents(year: year, month: month, day: day) else { return nil }
        return date
    }

    /// Validate the table before serving any entries. Each row contains a year followed by
    /// 24 zero-padded days, in the order of `names`; no runtime network or calendar feed.
    private static let daysByYear: [[Int]]? = {
        let rows = encodedDays.split(separator: "\n", omittingEmptySubsequences: false)
        guard rows.count == supportedYears.count else { return nil }
        var result: [[Int]] = []
        for (index, row) in rows.enumerated() {
            let fields = row.split(separator: ":", omittingEmptySubsequences: false)
            let year = supportedYears.lowerBound + index
            guard fields.count == 2, fields[0] == String(year) else { return nil }
            let bytes = Array(fields[1].utf8)
            guard bytes.count == names.count * 2, bytes.allSatisfy({ (48...57).contains($0) }) else { return nil }
            let leapYear = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)
            let monthLengths = [31, leapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            var days: [Int] = []
            days.reserveCapacity(names.count)
            for offset in stride(from: 0, to: bytes.count, by: 2) {
                let day = 10 * Int(bytes[offset] - 48) + Int(bytes[offset + 1] - 48)
                let monthIndex = offset / 4
                guard (1...monthLengths[monthIndex]).contains(day) else { return nil }
                if !(offset / 2).isMultiple(of: 2),
                   let previous = days.last, day <= previous { return nil }
                days.append(day)
            }
            result.append(days)
        }
        return result
    }()

